-- 76 Monster Zoo: every beast is one prefab and its variants - prefabs
-- whose own components carry a prefab_instance naming the prefab they
-- extend. Space spawns a newborn of each pen's prefab by name; the oldest
-- newborns leave as new ones come. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/76-monster-zoo.scene"
local PENS = { { "MzBeast", -320.0, 140.0 }, { "MzEmber", 320.0, 140.0 }, { "MzEmberGiant", -320.0, -180.0 }, { "MzSky", 320.0, -180.0 } }
local captions = true
local born = {}

function init(entity)
    math.randomseed(76)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then
        for _, pen in ipairs(PENS) do
            local e = Entity.spawn_prefab(pen[1])
            Transform.set_position(e, pen[2] + (math.random() - 0.5) * 300, pen[3] + 70)
            born[#born + 1] = e
        end
        while #born > 12 do Entity.destroy(table.remove(born, 1)) end
    end
end
